const r = await tools.exec_command({"cmd":"sed -n '300,345p' code/utils.py; python - <<'PY'
import numpy as np, glob, os, collections
E=np.load('data/beh/Imaging_Exp_info.npy',allow_pickle=True).item()
# Compare same behavior session across types
seen={}
for typ,es in E.items():
 B=np.load('data/beh/Beh_'+typ+'.npy',allow_pickle=True).item()
 for d in es:
  base=f"{d['mname']}_{d['datexp']}_{d['blk']}"; candidates=[k for k in B if k==base or k.startswith(base+'_')]
  if not candidates: print('MISSING',typ,base); continue
  # exp with stimtype likely key suffix
  key=base+'_'+d['stimtype'] if d.get('stimtype') and base+'_'+d['stimtype'] in B else candidates[0]
  x=B[key]
  sig=(x['ntrials'],tuple(x['UniqWalls']),tuple(x['stim_id']),len(x['ft']),tuple(x['WallName'][:5]))
  if base in seen and seen[base][0]!=sig: print('DIFF',base,seen[base][1],typ,seen[base][0],sig,'keys',key)
  else: seen[base]=(sig,typ)
print('mapped',len(seen))
# File totals
print('spkfiles',len(glob.glob('data/spk/*neural_data.npy')),'ret',len(glob.glob('data/retinotopy/*trans.npz')))
# sess# stats types
for typ,es in E.items(): print(typ,[d.get('sess#') for d in es])
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":30000});
